 function changed(target){if(target.id==='learning-file'){const file=target.files?.[0],callback=ui.pendingFile;ui.pendingFile=null;if(file&&callback)void callback(file).catch(error=>toast(error.message));return true;}if(target.matches('[data-block-check]')){page().blocks.find(b=>b.id===target.dataset.blockCheck).checked=target.checked;noteSave();return true;}if(target.matches('[data-block-type]')){const b=page().blocks.find(b=>b.id===target.dataset.blockType),type=target.value;if(['image','file','audio'].includes(type)){void pickFile(type==='image'?'image/*':type==='audio'?'audio/*':'.pdf,.md,.txt,application/pdf,text/plain',async file=>{const meta=await storeFile(file);l().assets.push(meta);b.type=type;b.assetId=meta.id;b.text=meta.name;noteSave();ctx.render();});}else if(type==='page'){modal('Link a notebook page',`<form data-lx-form="block-page" data-id="${e(b.id)}">${select('Page','pageId',l().pages.filter(p=>!p.trashed&&p.id!==page().id).map(p=>({value:p.id,label:p.title})), '')}<button class="button primary">Link page</button></form>`);}else{b.type=type;noteSave();ctx.render();}return true;}if(target.matches('[name=note-course]')){page().courseId=target.value;noteSave();return true;}if(target.matches('[data-note-parent]')){page().parentId=target.value;noteSave();return true;}if(target.matches('[data-reader-zoom]')){ui.readerZoom=Number(target.value);void renderPDF();return true;}if(target.matches('[data-forest-history]')){ui.forestDate=JSON.parse(target.dataset.dates)[Number(target.value)];ctx.render();return true;}return false;}
